from decimal import Decimal


def apply_growth(principal, rate_percent, periods, mode):
    values = (principal, rate_percent, periods)
    if any(not isinstance(value, Decimal) for value in values):
        raise ValueError("numeric arguments must be Decimal")
    if not all(value.is_finite() for value in values):
        raise ValueError("numeric arguments must be finite")
    if principal < 0 or rate_percent < Decimal("-100"):
        raise ValueError("numeric argument out of range")
    if periods < 0 or periods != periods.to_integral_value():
        raise ValueError("periods must be a non-negative integer")
    if mode not in ("single", "compound"):
        raise ValueError("invalid mode")
    factor = Decimal(1) + rate_percent / Decimal(100)
    if mode == "single":
        if periods != Decimal(1):
            raise ValueError("single mode requires one period")
        return principal * factor
    return principal * factor ** max(1, int(periods))

